cat > src/app/reset-password/page.tsx <<'EOF'
import { redirect } from "next/navigation";
import { resetPassword } from "@/lib/users";

const MIN_PASSWORD_LENGTH = 8;

async function submit(formData: FormData) {
  "use server";
  const token = String(formData.get("token") ?? "");
  const password = String(formData.get("password") ?? "");
  if (password.length < MIN_PASSWORD_LENGTH) {
    redirect(`/reset-password?token=${encodeURIComponent(token)}&error=short`);
  }
  const user = await resetPassword(token, password);
  redirect(user ? "/reset-password?done=1" : "/reset-password?error=invalid");
}

export default async function ResetPasswordPage({
  searchParams,
}: {
  searchParams: Promise<{ token?: string; done?: string; error?: string }>;
}) {
  const { token, done, error } = await searchParams;

  return (
    <main className="mx-auto max-w-sm p-8">
      <h1 className="text-2xl font-semibold">Choose a new password</h1>
      {done ? (
        <p className="mt-4 text-sm">Your password has been updated.</p>
      ) : error === "invalid" || !token ? (
        <p className="mt-4 text-sm">
          This reset link is invalid or has expired.{" "}
          <a href="/forgot-password" className="underline">
            Request a new one
          </a>
          .
        </p>
      ) : (
        <form action={submit} className="mt-4 space-y-3">
          <input type="hidden" name="token" value={token} />
          <input
            name="password"
            type="password"
            required
            minLength={MIN_PASSWORD_LENGTH}
            placeholder="New password"
            className="w-full rounded border px-3 py-2 text-sm"
          />
          {error === "short" && (
            <p className="text-sm text-red-600">
              Use at least {MIN_PASSWORD_LENGTH} characters.
            </p>
          )}
          <button type="submit" className="rounded bg-black px-4 py-2 text-sm text-white">
            Update password
          </button>
        </form>
      )}
    </main>
  );
}
EOF
