const sent: any[] = [];
let fail = false;
globalThis.fetch = (async (url: string, init: any) => {
  if (fail) return new Response(JSON.stringify({ ErrorCode: 406, Message: "Inactive recipient" }), { status: 422, headers: { "content-type": "application/json" } });
  sent.push({ url, token: init.headers["X-Postmark-Server-Token"], body: JSON.parse(init.body) });
  return new Response(JSON.stringify({ ErrorCode: 0, Message: "OK", MessageID: "x", To: "", SubmittedAt: "" }), { status: 200, headers: { "content-type": "application/json" } });
}) as any;
process.env.POSTMARK_SERVER_TOKEN = "test-token";
process.env.POSTMARK_FROM_EMAIL = "hello@notely.test";
process.env.APP_URL = "https://notely.test/";

