await u.requestPasswordReset("nobody@example.com");
console.log("unknown email sent nothing:", sent.length === 1);
await u.requestPasswordReset("new@example.com");
const token = new URL(sent[1].body.TextBody.match(/https:\S+/)[0]).searchParams.get("token");
console.log("reset:", sent[1].body.Subject, !!token);
console.log("bad token:", await u.resetPassword("nope", "x12345678"));
